LESSON_BY_ID = {c['id']:c for c in LESSONS}
NAV_LABELS = ['Learning journey'] + [c['nav'] for c in LESSONS] + ['Cell foundations','Glossary','My learning notebook']


def source_markdown(keys):
    return ' · '.join(f'[{SOURCES[key][0]}]({SOURCES[key][1]})' for key in dict.fromkeys(keys))


def task_stages(lesson_id, signal, readout):
    """A source-backed interpretation of task phases; no voxel or firing estimate."""
    lesson = LESSON_BY_ID[lesson_id]
    last = signal.onset_ms + (0 if signal.kind=='pattern' else (len(signal.content)-1)*signal.gap_ms) + 5
    stages = [
        dict(start=0., end=signal.onset_ms, label='Prepare a goal', regions=['pfc','parietal'],
             why='A task needs a goal and selected information. Frontal–parietal interactions contribute to control and attention. The model receives a preset protocol, not an internally chosen goal.', sources=['human_wm','parietal_human']),
        dict(start=signal.onset_ms, end=last, label='Encode the input', regions=['occipital','thalamus','temporal'],
             why='For a human looking at these symbols or pixels, visual pathways transform the input and temporal pathways help identify features. Our source cells instead receive engineered current pulses.', sources=['visual_streams','thalamic_attention']),
        dict(start=last, end=readout, label='Combine recent evidence', regions=['pfc','temporal'],
             why='Using recent information can recruit distributed memory and control networks. In this circuit, delayed spikes and decaying synaptic effects preserve recent input; this is a mechanistic analogy, not a regional activity measurement.', sources=['pfc_cells','human_wm']),
        dict(start=readout, end=readout+20.001, label='Read out and respond', regions=['pfc','basal','motor','cerebellum','thalamus'],
             why='A real task response would involve interacting selection and motor systems. The software reads passive class voltages once at the marked time. No human movement, outcome or dopamine signal is simulated in this replay.', sources=['motor_cells','bg_circuit','cerebellar_outputs']),
    ]
    # The focused structure joins only the phase its lesson actually discusses.
    phase = {'pfc':2,'occipital':1,'cerebellum':3,'temporal':2,'parietal':0,'hippocampus':2,
             'basal':3,'motor':3,'thalamus':1,'amygdala':2,'hypothalamus':0,'brainstem':0}[lesson_id]
    if lesson_id not in stages[phase]['regions']: stages[phase]['regions'].append(lesson_id)
    stages[phase]['why'] += ' Lesson connection: ' + lesson['coordination']
    stages[phase]['sources'] = list(dict.fromkeys(stages[phase]['sources'] + lesson['sources'][:1]))
    if lesson_id in ('amygdala','hypothalamus','brainstem'):
        stages[phase]['why'] += ' This is an abstract lesson connection: the neutral class task does not establish recruitment of this structure, emotional learning, homeostatic regulation or arousal.'
    return stages
